@differentiable(reverse)
private func testFunc1(a: [Float], b: [Float]) -> Float {
    let n = withoutDerivative(at: min(a.count, b.count))
    var sum: Float = 0
    for i in 0 ..< n {
        let a1 = a[i]
        let b1 = b[i]
        let t0 = (b1 > 0 ? Float(-0.6260) : a1)
        sum += t0
    }
    return sum
}

private let x2: Float = 0.219949
@differentiable(reverse)
private func testFunc2(x: Float) -> Float {
    let t0 = min(Float(-0.7693), x2)
    let t1 = min(Float(-1.1383), t0)
    let t2 = min(t1, x2)
    let t3 = (t2 + x2)
    let t4 = abs(t3)
